INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('ASAP! Summer Camp', 'After School Arts Program, Inc. (ASAP!)', 'https://asapct.org/programs/summer-camp/', NULL, 'asap@asapct.org', '860-868-0740', 'Rumsey Hall School, 201 Romford Road', 'Washington', 'CT', '06794', 'Connecticut', 'day', ARRAY['arts','performing_arts','nature']::text[], NULL, ARRAY['sculpture','cooking','theater','circus arts','high wire','adventure course','nature hikes','tie-dye','music','creative movement','fort building','entomology','drumming','rock climbing','makerspace','weaving','jewelry','painting','face painting','crafting','field trips']::text[], NULL, NULL, NULL, 1, 10, 'An arts and outdoor day camp for grades 1-10, held in August at Rumsey Hall School in Washington, CT, from 9:00 am to 3:30 pm. Professional teaching artists lead visual, culinary and performing arts, plus nature hikes, an adventure course, climbing and field trips.', NULL, NULL, 800, 900, NULL, NULL, NULL, TRUE, FALSE, TRUE, 'Full tuition refund for cancellations before June 1; 50% refund for cancellations June 1-30; no refund for cancellations on or after July 1.', NULL, NULL, NULL, NULL, 2027, 'f25ee891-d70c-5279-9e00-54b90b2329a1', 'asap-summer-camp-washington', ST_GeogFromText('SRID=4326;POINT(-73.3102 41.6562)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://asapct.org/contact/','https://asapct.org/programs/summer-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Auer Camp', 'The 4-H Center at Auerfarm, Inc.', 'https://auerfarm.org/summercamps/', NULL, 'jmarshall@auerfarm.org', '860-242-7144', '158 Auer Farm Road', 'Bloomfield', 'CT', '06002', 'Connecticut', 'day', ARRAY['nature','STEM','arts']::text[], NULL, ARRAY['Barn exploration / farm animal care','Play forest and fort building','Hiking and survival skills','Garden exploration','Stream exploration and fishing','Arts & crafts / tie-dye','Science exploration','Cooking','Hayrides','Sports and games','Leadership skills (grades 9-10)']::text[], NULL, 3, 15, 0, 10, 'A farm-based day camp on a 120-acre farm in Bloomfield, CT, for ages 3-15. Summer 2027 runs for 7 weeks, June 21 to August 6, with a S.T.E.A.M. curriculum built around farm animals, gardening, nature exploration and arts. Groups run from a half-day Sprouts program (ages 3-5) up to a leadership program for grades 9-10. Registration opens January 1, 2027.', NULL, NULL, 370, 395, 395, 'week', TRUE, NULL, NULL, NULL, 'Cancellation fees depend on how much notice you give: $75 for more than 30 days, $200 for 14-30 days, $300 for less than 2 weeks.', 'Sprouts (ages 3-5) must be fully potty-trained. Barn activities are adjusted for each child''s age and comfort.', 'No pool or swim program is described. Older campers may explore, fish and play in a stream on the farm.', NULL, NULL, 2027, 'e647e9b2-1c9d-5163-b5ec-c2a97aed36cd', 'auer-camp-bloomfield', ST_GeogFromText('SRID=4326;POINT(-72.741 41.8438)'), TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://auerfarm.org/summercamps/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Buck''s Rock Camp', 'Buck''s Rock Camp, Inc.', 'https://bucksrockcamp.org', NULL, 'info@bucksrockcamp.org', '(860) 354-5030', '59 Buck''s Rock Road', 'New Milford', 'CT', '06776', 'Connecticut', 'sleepaway', ARRAY['arts','performing_arts']::text[], NULL, ARRAY['Visual arts','Performing arts','Outdoor activities']::text[], NULL, 11, 17, NULL, NULL, 'Buck''s Rock is a nonprofit overnight arts camp in New Milford, CT, for teens ages 11 to 17, with 32 visual and performing arts programs plus outdoor activities. In 2027 you can book the 8-week full season (July 1 to August 21), a 4-week first or second session, a 6-week session, or the CIT program. Tuition is tiered by household size and income, from $0 up to the full rate.', NULL, NULL, 9275, 15991, NULL, NULL, NULL, NULL, TRUE, TRUE, NULL, NULL, 'The camp has a swimming pool on its wooded grounds.', NULL, NULL, 2027, '4f07bd61-37ca-59d5-8253-25adfe5324c6', 'buck-s-rock-camp-new-milford', ST_GeogFromText('SRID=4326;POINT(-73.4228 41.6013)'), FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://bucksrockcamp.org/dates','https://bucksrockcamp.org/faqs','https://bucksrockcamp.org/rates']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Awosting', 'Ebner Camps Inc.', 'https://awosting.com/', 'https://awosting.campintouch.com/ui/forms/application/camper/App', NULL, '(860) 567-4924', '296 West Street', 'Morris', 'CT', '06763', 'Connecticut', 'sleepaway', ARRAY['sports','adventure']::text[], NULL, ARRAY['Motocross','Go-karts','High ropes','Climbing','Archery','Wakeboarding','Waterskiing','Wakesurfing','Sailing','Canoeing','Kayaking and rowing','Stand-up paddleboard','Swimming','Fishing','Soccer','Baseball','Basketball','Lacrosse','Fencing','Mountain biking','Arts and crafts','Woodshop','Ceramics','Music','Drama','Overnight camping']::text[], 'boys', 7, 16, NULL, NULL, 'Camp Awosting is an overnight summer camp for boys ages 7 to 16 on Bantam Lake in Morris, Connecticut, with 40+ activities including motor sports, waterskiing, high ropes and team sports. Summer 2027 sessions run from 1 to 8 weeks between June 27 and August 21. Tuition covers meals, snacks, laundry, towel service, gratuities, the canteen shop and all on-camp activities.', NULL, NULL, 2675, 13230, NULL, NULL, NULL, TRUE, TRUE, NULL, 'Half of the deposit cannot be refunded under any circumstances, and the whole deposit becomes non-refundable after 12/31/26. Balances are due May 1. Unused canteen money is not refunded. Families in the Guaranteed Tuition Program pay no deposit; they pay half the tuition by November 15 and half by January 15.', NULL, 'The waterfront is on Bantam Lake, with swimming, sailing, canoeing, kayaking, waterskiing, a water trampoline and inflatables. Life vests are required on the water trampoline.', NULL, NULL, 2027, '0bbfa743-c5c3-5a7a-a9d2-e81d36eaa702', 'camp-awosting-morris', ST_GeogFromText('SRID=4326;POINT(-73.21 41.6943)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://awosting.com/','https://awosting.com/activities/','https://awosting.com/dates-rates/','https://awosting.com/future-families/faqs/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Chinqueka', 'Ebner Camps Inc.', 'https://chinqueka.com/', 'https://chinqueka.campintouch.com/ui/forms/application/camper/App', NULL, '860-567-9678', '1519 Bantam Road', 'Bantam', 'CT', '06750', 'Connecticut', 'sleepaway', ARRAY['sports','arts','adventure']::text[], NULL, ARRAY['Horseback riding (extra fee)','Climbing and zip line','High ropes','Archery','Go-karts','Waterskiing','Sailing','Canoeing','Kayaking and rowing','Paddleboarding','Swimming','Synchronized swimming','Soccer','Field hockey','Tennis','Gymnastics','Cheerleading','Dance','Drama','Music','Ceramics','Arts and crafts','Jewelry making','Photography','Culinary arts','STEM','Overnight camping']::text[], 'girls', 7, 16, NULL, NULL, 'Camp Chinqueka is an overnight summer camp for girls ages 7 to 16 in Bantam, Connecticut, with sessions from one week (Rookie) to a full eight-week season between June 27 and August 21, 2027. Activities range from waterskiing, sailing and climbing to dance, ceramics and horseback riding. Tuition includes meals, snacks, laundry, towel service, gratuities, the canteen shop and all on-camp activities.', NULL, NULL, 2675, 13230, NULL, NULL, NULL, TRUE, TRUE, NULL, 'Half of the deposit cannot be refunded under any circumstances, and the whole deposit becomes non-refundable after 12/31/26. Balances are due May 1. Unused canteen money is not refunded.', NULL, 'Campers get swim instruction from American Red Cross certified counselors, from Level 1 to Lifeguard Training, plus free swim in the camp''s lake. Waterskiing, shared with Camp Awosting, is on Bantam Lake, 7 miles away.', NULL, NULL, 2027, '77ccd8ad-838d-5024-93a3-36c43379ece4', 'camp-chinqueka-bantam', ST_GeogFromText('SRID=4326;POINT(-73.2423 41.7247)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://chinqueka.com/','https://chinqueka.com/activities/','https://chinqueka.com/dates-rates/','https://chinqueka.com/future-families/faqs/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Farmington Valley', 'YMCA of Greater Hartford (Farmington Valley YMCA)', 'https://www.ghymca.org/camps/farmington-valley-ymca-camp-farmington-valley', NULL, 'campfvy@ghymca.org', '860 653 5524', '97 Salmon Brook Street', 'Granby', 'CT', '06035', 'Connecticut', 'day', ARRAY['sports','arts','nature','STEM']::text[], NULL, ARRAY['Field trips','Gaga','Arts & Crafts','Free swim','Swim instruction','Archery','Rock wall','Nature adventures','Camp songs','S.T.E.M.','Sports','Basketball','Team building','Large group games']::text[], NULL, NULL, NULL, 0, 8, 'A state-licensed YMCA day camp in Granby, CT, for children entering kindergarten through 8th grade. Each week has a theme, and activities include swim lessons, archery, a climbing wall, arts and crafts, nature and field trips.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, TRUE, 'Deposits are nonrefundable and can only be transferred within the current camp year. No refunds for cancellations made within 4 weeks of a session''s start. If you ask in writing, paid fees can be moved to another week if there is space. The remaining balance is drafted 4 weeks before each session.', NULL, 'The camp has an indoor pool. The program includes free swim and swim instruction.', NULL, NULL, 2026, '383d6317-b55b-5e85-b9a1-f0a9c440bda3', 'camp-farmington-valley-granby', ST_GeogFromText('SRID=4326;POINT(-72.8302 41.9715)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.ghymca.org/camps/farmington-valley-ymca-camp-farmington-valley']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Glawackus (Glastonbury YMCA)', 'YMCA of Greater Hartford', 'https://www.ghymca.org/camps/glastonbury-ymca-camp-glawackus', NULL, 'campglawackus@ghymca.org', '860-633-6548', '30 High Street', 'South Glastonbury', 'CT', '06073', 'Connecticut', 'day', ARRAY['sports','arts','STEM','nature']::text[], NULL, ARRAY['Archery','Arts & Crafts','STEM','Nature activities','Sports','Basketball','Volleyball','Gaga pit','Large group games','Songs, skits & plays','Team building','Swimming','Field trips','Hiking (teen camp)','Community service (teen camp)']::text[], NULL, 5, 15, NULL, NULL, 'YMCA day camp for ages 5-11 and teen camp for ages 12-15 in South Glastonbury. Activities include archery, arts and crafts, STEM, nature, sports, weekly field trips and swimming. Teen campers also visit Connecticut attractions, hike and do a service project each week.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, TRUE, 'Deposits cannot be refunded and can only be transferred within the current camp year. There are no refunds for cancellations within 4 weeks of a session''s start. If you ask in writing, paid fees may be moved to another week when space is available. The rest of the balance is charged 4 weeks before each session.', NULL, 'Day camp swims weekly at the Downtown YMCA, with some weeks also including swimming at YMCA Camp Chase. Teen camp swims once per week. Staff receive water safety training.', NULL, NULL, 2026, 'b85180d8-aeda-54df-a923-f55c5890ba56', 'camp-glawackus-glastonbury-ymca-south-glastonbury', ST_GeogFromText('SRID=4326;POINT(-72.5522 41.6919)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.ghymca.org/camps/glastonbury-ymca-camp-glawackus']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Laurelwood', NULL, 'https://www.camplaurelwood.org/', 'https://laurelwood.campintouch.com/ui/forms/application/camper/App', 'info@camplaurelwood.org', '(203) 421-3736', '463 Summer Hill Rd.', 'Madison', 'CT', '06443', 'Connecticut', 'sleepaway', ARRAY['faith','general']::text[], NULL, NULL, NULL, NULL, NULL, 0, 11, 'Jewish summer camp in Madison, CT. Overnight camp for grades 2-9 in sessions from 2 to 7 weeks, a day camp for rising K-7th graders that can be booked by the week, the Bonim travel program (grades 10-11) and an SIT program (grade 11). Overnight tuition is all-inclusive.', NULL, NULL, 685, 12655, NULL, 'session', TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '5390b301-a793-54a2-8295-0167bc9057bb', 'camp-laurelwood-madison', ST_GeogFromText('SRID=4326;POINT(-72.6245 41.3445)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.camplaurelwood.org/dates-and-rates-day-camp/','https://www.camplaurelwood.org/dates-and-rates-overnight-camp/','https://www.camplaurelwood.org/dates-and-rates/','https://www.camplaurelwood.org/tuition-assistance/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Sloane YMCA Day Camp', 'Camp Sloane YMCA', 'https://campsloane.org/day-camp', 'https://campsloane.campintouch.com/ui/forms/application/camper/App', 'info@campsloane.org', '(860) 435-2557', '124 Indian Mountain Rd', 'Lakeville', 'CT', '06039', 'Connecticut', 'day', ARRAY['sports','arts','nature']::text[], NULL, ARRAY['Sports','Arts and crafts','Boating','Adventure','Instructional swimming','Horseback riding lessons (extra fee)']::text[], NULL, NULL, NULL, 0, 6, 'A day camp for children entering grades K-6, run 8:45am-4:45pm at Camp Sloane YMCA in Lakeville, CT. Campers are grouped by rising grade and do sports, arts and crafts, boating, adventure activities and daily swim lessons. Lunch and an afternoon snack are included.', NULL, NULL, 480, 1115, 560, 'week', TRUE, NULL, TRUE, TRUE, NULL, NULL, 'Instructional swim lessons every day. Boating is one of the day camp activities.', NULL, NULL, 2027, '1a92d53b-a971-54bc-8051-e4c90b1f0fda', 'camp-sloane-ymca-day-camp-lakeville', ST_GeogFromText('SRID=4326;POINT(-73.4433 41.9621)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://campsloane.org/dates-and-rates','https://campsloane.org/day-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Sloane YMCA', NULL, 'https://campsloane.org', 'https://campsloane.campintouch.com/ui/forms/application/camper/App', 'info@campsloane.org', '(860) 435-2557', '124 Indian Mountain Rd', 'Lakeville', 'CT', '06039', 'Connecticut', 'sleepaway', ARRAY['sports','nature','outdoor']::text[], NULL, ARRAY['Horseback riding','Waterskiing','Swimming','High ropes and zip line','Gaga','Tennis','Basketball','Soccer','American Red Cross Lifeguard course (LEAD)','Teen leadership (LEAD)']::text[], NULL, NULL, NULL, 4, 11, 'Overnight YMCA camp in Lakeville, CT, for rising 4th-10th graders, with a LEAD teen leadership program for rising 11th graders. Campers live in platform tents in villages grouped by grade and choose their own activities, with riding and waterski lessons on offer. Four 2-week sessions, one 1-week session and a 2-week Riding Camp. The day camp is listed separately.', NULL, NULL, 1325, 3495, 1625, 'session', NULL, NULL, TRUE, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, 'c209a7a3-d993-56f2-9566-93cefe96a45f', 'camp-sloane-ymca-lakeville', ST_GeogFromText('SRID=4326;POINT(-73.4433 41.9621)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://campsloane.org/dates-and-rates','https://campsloane.org/overnight-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Arcadia Nature Camp', 'Mass Audubon', 'https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/arcadia/camp', NULL, NULL, '413-276-7611', '127 Combs Road', 'Easthampton', 'MA', '01027', 'Central & Western Massachusetts', 'day', ARRAY['nature']::text[], NULL, ARRAY['Hiking','Habitat exploration','Animal and plant identification','Games','Crafts','Scavenger hunts','Storytelling','Canoeing (ages 10-12)','Nature photography (specialty week)','Environmental leadership (specialty week)']::text[], NULL, 5, 15, NULL, NULL, 'A Mass Audubon nature day camp for ages 5–15 at Arcadia Wildlife Sanctuary in Easthampton, Monday to Friday, 9 am to 3 pm. Campers hike, play games, make crafts and explore forests, meadows, streams and vernal pools, with specialty weeks for nature photography and environmental leadership.', NULL, NULL, 107, 535, NULL, 'week', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, TRUE, 'https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/arcadia/camp/about-camp', 2026, '551393be-6981-5628-8130-8dd76b2c8efd', 'arcadia-nature-camp-easthampton', ST_GeogFromText('SRID=4326;POINT(-72.6708 42.2654)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/arcadia','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/arcadia/camp','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/arcadia/camp/about-camp','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/arcadia/camp/programs-pricing']::text[], '2026-11-13', '2026-11-13', TRUE),
('Belvoir Terrace', NULL, 'https://www.belvoirterrace.com/', 'https://belvoirterrace.campintouch.com/ui/forms/application/camper/App', 'info@belvoirterrace.com', '413-637-0555', '80 Cliffwood St.', 'Lenox', 'MA', '01240', 'Central & Western Massachusetts', 'sleepaway', ARRAY['arts','performing_arts','sports']::text[], NULL, ARRAY['Studio art','Ballet','Dance','Music','Theater','Swimming','Tennis','Horseback riding','Archery','Fencing','Basketball','Soccer','Volleyball','Outdoor education (younger campers)','Trips to cultural venues']::text[], 'girls', NULL, NULL, 2, 10, 'An overnight summer camp for girls in grades 2 to 10 in Lenox, Massachusetts. Campers choose all their own classes in art, dance, music, theater and individual sports, taught by professional staff, in 6, 5 or 3 week sessions.', NULL, NULL, 13500, 17400, NULL, 'session', NULL, NULL, TRUE, NULL, NULL, NULL, 'Swimming classes with professional instruction, plus beach days at Camp Greylock.', NULL, NULL, 2027, '03ba85fa-dfdd-5b90-927a-84f7942b8ae3', 'belvoir-terrace-lenox', ST_GeogFromText('SRID=4326;POINT(-73.2698 42.3679)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.belvoirterrace.com/','https://www.belvoirterrace.com/camp-life/','https://www.belvoirterrace.com/dates-rates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Berkshire Nature Camp at Pleasant Valley', 'Mass Audubon', 'https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/pleasant-valley/camp', 'https://www.massaudubon.org/programs-events/nature-camps/registration-instructions', NULL, '413-728-1545', '472 West Mountain Road', 'Lenox', 'MA', '01240', 'Central & Western Massachusetts', 'day', ARRAY['nature']::text[], NULL, ARRAY['Trail exploration and hiking','Wildlife observation','Outdoor play and games','Crafts','Songs and stories','Pond exploration','Building survival shelters','Plant and animal identification','Field science techniques','Leadership training (CIT)']::text[], NULL, 4, 17, NULL, NULL, 'Weekly outdoor nature day camp at Mass Audubon''s Pleasant Valley Wildlife Sanctuary in Lenox, Monday to Friday, 9 am to 3 pm. Groups for ages 4 to 12 explore trails, ponds and forests, play games and make crafts, and there is a Counselor-in-Training program for ages 14 to 17.', NULL, NULL, 104, 518, NULL, 'week', NULL, NULL, NULL, TRUE, NULL, 'Campers must be able to move about on uneven terrain because camp is outdoors and exploratory.', NULL, TRUE, 'https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/pleasant-valley/camp/about-camp', 2026, 'a50075c7-45be-58c4-b539-a61343fb0c22', 'berkshire-nature-camp-at-pleasant-valley-lenox', ST_GeogFromText('SRID=4326;POINT(-73.2698 42.3679)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/pleasant-valley','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/pleasant-valley/camp','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/pleasant-valley/camp/about-camp','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/pleasant-valley/camp/programs-pricing']::text[], '2026-11-13', '2026-11-13', TRUE),
('Broad Meadow Brook Nature Camp', 'Mass Audubon', 'https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/broad-meadow-brook/camp', 'https://www.massaudubon.org/programs-events/nature-camps/registration-instructions', NULL, '508-640-5615', '414 Massasoit Road', 'Worcester', 'MA', '01604', 'Central & Western Massachusetts', 'day', ARRAY['nature','STEM']::text[], NULL, ARRAY['Hiking','Arts and crafts','Games','Birding','Stream restoration project','Animal adaptations','Habitat and wildlife exploration','Animal identification','Team building','Leadership training']::text[], NULL, 4, 16, NULL, NULL, 'Mass Audubon day camp at Broad Meadow Brook Wildlife Sanctuary in Worcester for ages 4.5 to 16, with most of the day spent outdoors hiking, exploring habitats and doing nature projects. Options include a three-day mini camp, weekly camp by age group, a field-trip specialty week, a Counselor-in-Training program, and before and after care.', NULL, NULL, 42, 518, NULL, NULL, TRUE, NULL, FALSE, TRUE, NULL, NULL, NULL, TRUE, 'https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/broad-meadow-brook/camp/about-broad-meadow-brook-nature-camp', 2026, 'bb5c6fc4-9e7f-5522-afe6-76555cc8af7e', 'broad-meadow-brook-nature-camp-worcester', ST_GeogFromText('SRID=4326;POINT(-71.8023 42.2626)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/broad-meadow-brook','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/broad-meadow-brook/camp','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/broad-meadow-brook/camp/about-broad-meadow-brook-nature-camp','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/broad-meadow-brook/camp/programs-pricing']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Danbee', NULL, 'https://www.campdanbee.com/', 'https://danbee.campintouch.com/ui/forms/application/camper/App', 'info@campdanbee.com', '413-655-8115', '101 West Main Road', 'Peru', 'MA', '01235', 'Central & Western Massachusetts', 'sleepaway', ARRAY['sports','arts','performing_arts','nature']::text[], NULL, ARRAY['Swimming (lake and two heated pools)','Waterskiing and wakeboarding','Sailing','Paddleboarding','Canoeing and kayaking','Tennis','Soccer and team sports','Gymnastics and cheerleading','Horseback riding (extra fee)','Ice hockey (extra fee)','Archery','Ropes and climbing wall','Arts and crafts','Pottery','Jewelry','Woodcraft','Culinary arts','Theater','Dance','Journalism and media','Camping and hiking','Day and overnight trips','Community service']::text[], 'girls', NULL, NULL, 1, 9, 'An overnight camp for girls finishing 1st through 9th grade on Lake Ashmere in the Berkshires. Over 30 activities, from waterskiing and tennis to theater, gymnastics and pottery, with a 1:3 counselor to camper ratio and an emphasis on skill building over competition.', NULL, NULL, 800, 16950, NULL, 'session', NULL, TRUE, TRUE, NULL, NULL, NULL, 'Campers swim in Lake Ashmere and in two heated pools. The waterfront offers waterskiing, wakeboarding, sailing, paddleboarding, canoeing, kayaking and fishing.', NULL, NULL, 2027, 'c6168d5f-afe0-526a-abf9-51bb8f172466', 'camp-danbee-peru', ST_GeogFromText('SRID=4326;POINT(-73.0353 42.4082)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.campdanbee.com/about/','https://www.campdanbee.com/about/dates-and-rates/','https://www.campdanbee.com/about/faqs/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Farley Day Camp', 'Camp Farley', 'https://campfarley.com/camp-options/day-camp', 'https://campfarley.campbrainregistration.com', 'office@campfarley.com', '508-477-0181', '615 Route 130', 'Mashpee', 'MA', '02649', 'Central & Western Massachusetts', 'day', ARRAY['sports','arts','nature']::text[], NULL, ARRAY['Swimming','Canoeing and kayaking','Archery','Arts and crafts','Nature','Sports and games','Music','Theater','Fishing','Barnyard animals']::text[], NULL, 4, 15, NULL, NULL, 'Weekday day camp in Mashpee on Cape Cod for ages 6 to 15, with swimming, boating, archery, arts and crafts, nature and sports. Sprouts, for ages 4 and 5, runs full or half days. Eight weekly sessions in summer 2027.', NULL, NULL, 305, 610, 610, 'week', NULL, FALSE, FALSE, NULL, '$100 deposit per camper is non-refundable and non-transferable. Cancel by March 31, 2027: full refund minus the deposit and a $25 admin fee. April 1 to May 31, 2027: camp keeps the deposit plus 25% of tuition. June 1, 2027 or later: no refund. Prorated refunds for acute medical illness or injury with a doctor''s note, at the camp''s discretion. No refunds for early departures or late arrivals. Any balance is charged automatically on June 1, 2027.', NULL, NULL, TRUE, 'https://campfarley.com/about-us/general-information', 2027, '30c5f729-bab2-5bed-9427-e1353f933aee', 'camp-farley-day-camp-mashpee', ST_GeogFromText('SRID=4326;POINT(-70.4927 41.6176)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://campfarley.com/about-us/general-information','https://campfarley.com/about-us/programs-and-activities','https://campfarley.com/camp-options/day-camp','https://campfarley.com/rates-and-dates','https://geocoding.geo.census.gov/geocoder/locations/address?street=615+Route+130&city=Mashpee&state=MA&benchmark=Public_AR_Current&format=json']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Greylock', NULL, 'https://campgreylock.com/', 'https://greylock.campintouch.com/ui/forms/application/camper/App', NULL, '(413) 623-8921', '1525 Main Street', 'Becket', 'MA', '01223', 'Central & Western Massachusetts', 'sleepaway', ARRAY['sports','arts','nature']::text[], NULL, ARRAY['Baseball','Basketball','Soccer','Lacrosse','Tennis','Golf','Flag football','Volleyball','Roller hockey','Swimming','Sailing','Boating and canoeing','Waterskiing','Wakeboarding','Tubing','Fishing','Archery','Fencing','Climbing wall','Ropes course','Zip line','Mountain biking','Hiking and overnights','Art','Drama','Radio and electronics','Nature','Trips']::text[], 'boys', 6, 16, NULL, NULL, 'A traditional overnight camp for boys ages 6 to 16 on Center Lake in Becket, Massachusetts. The program covers land sports, watersports, arts and adventure, and campers are split evenly between junior and senior groups.', NULL, NULL, 11600, 17100, NULL, 'session', NULL, NULL, NULL, NULL, NULL, NULL, 'Lakefront campus on Center Lake. Activities include swimming, sailing, boating, canoeing, waterskiing, wakeboarding and tubing.', TRUE, 'https://campgreylock.com/', 2027, '2b16e37d-7b55-5b0f-8938-0ed1ee74a555', 'camp-greylock-becket', ST_GeogFromText('SRID=4326;POINT(-73.0848 42.2865)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://campgreylock.com/','https://campgreylock.com/about-greylock/activities','https://campgreylock.com/contact-us','https://campgreylock.com/dates-fees']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Mah-Kee-Nac – Mini Mak Two-Week Sleepaway Camp', NULL, 'https://www.campmkn.com/future-families/mini-mak-two-week-camp/', 'https://mkn.campintouch.com/ui/forms/application/camper/App', 'office@campmkn.com', '413-274-4092', '6 Hawthorne Rd', 'Lenox', 'MA', '01240', 'Central & Western Massachusetts', 'sleepaway', ARRAY['sports','nature']::text[], NULL, ARRAY['swimming','sports','soccer','ropes course','paddling','arts','evening programs','trip day']::text[], NULL, NULL, NULL, 1, 5, 'A two-week sleepaway session for boys new to Camp Mah-Kee-Nac who are entering grades 1–5. Campers live in Junior Camp cabins and do all the regular camp activities. Families can choose to extend into the full session.', NULL, NULL, 6300, 6300, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, 'Campers swim and paddle in the lake. The page does not describe swim instruction, swim tests or lifeguard staffing.', NULL, NULL, 2027, 'ec3c6d4c-d17a-5d49-8f2b-c7f13e76134a', 'camp-mah-kee-nac-mini-mak-two-week-sleepaway-camp-lenox', ST_GeogFromText('SRID=4326;POINT(-73.2698 42.3679)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://www.campmkn.com/future-families/mini-mak-two-week-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Taconic', NULL, 'https://camptaconic.com/', NULL, 'info@camptaconic.com', '201-871-2086', '770 New Windsor Road', 'Hinsdale', 'MA', '01235', 'Central & Western Massachusetts', 'sleepaway', ARRAY['sports','arts','performing_arts','adventure']::text[], NULL, ARRAY['baseball','basketball','soccer','lacrosse','flag football','tennis','golf','archery','gymnastics','swimming','sailing','waterskiing','canoeing','stand up paddle boarding','fishing','climbing wall','aerial park','low ropes','circus (trapeze, tight rope, juggling)','horseback riding','musical theater','dance','ceramics','woodworking','cooking','Lego/robotics','digital photography']::text[], NULL, 7, 15, NULL, NULL, 'Camp Taconic is a coed sleepaway camp for ages 7 to 15 on Lake Ashmere in Hinsdale, in the Berkshires. For 2027 it offers a full season from late June to mid-August, plus a four-week part season for first-summer campers only.', NULL, NULL, 11300, 17200, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '2f5f1822-b9d5-5eb6-b869-e97bb68caa10', 'camp-taconic-hinsdale', ST_GeogFromText('SRID=4326;POINT(-73.1128 42.4358)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://camptaconic.com/faq.php','https://camptaconic.com/our-activities.php','https://camptaconic.com/rates-dates.php']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Winadu', NULL, 'https://campwinadu.com/summer/dates-rates', 'https://winadu.campintouch.com/ui/forms/application/camper/App', 'directors@campwinadu.com', '914-437-7200', '700 Churchill Street', 'Pittsfield', 'MA', '01201', 'Central & Western Massachusetts', 'sleepaway', ARRAY['sports','arts','nature']::text[], NULL, ARRAY['Team sports','Individual sports','Ice hockey','Golf','Waterfront','Outdoor adventure','Arts & hobbies','Special events']::text[], NULL, NULL, NULL, NULL, NULL, 'Boys'' sleepaway camp in the Berkshire Mountains near Pittsfield, Massachusetts. Offers a full summer season and a 5-week option for new younger campers, with team and individual sports, ice hockey, waterfront, outdoor adventure, and arts.', NULL, NULL, 13800, 16950, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '661dde27-4989-530f-ac22-84a5d9bfa4f0', 'camp-winadu-pittsfield', ST_GeogFromText('SRID=4326;POINT(-73.2607 42.4518)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://campwinadu.com/contact-us','https://campwinadu.com/summer/dates-rates']::text[], '2026-11-13', '2026-11-13', TRUE),
('Discovery Adventures', 'Old Sturbridge Village', 'https://www.osv.org/education/discovery-adventures/', NULL, 'osved@osv.org', '(508) 347-0274', '1 Old Sturbridge Village Road', 'Sturbridge', 'MA', '01566', 'Central & Western Massachusetts', 'day', ARRAY['academic','arts']::text[], NULL, ARRAY['hearth cooking','19th-century crafts','farm and garden chores','19th-century games','sewing and quilting','blacksmithing, pottery and woodwork (ages 11-14)','militia drills (ages 11-14)','art (watercolor, charcoal, pinch pots)']::text[], NULL, 6, 17, NULL, NULL, 'Week-long themed history day programs at Old Sturbridge Village, a living history museum. In summer, kids ages 6 to 17 spend 9 a.m. to 3 p.m. in 19th-century costume, cooking over the open hearth, doing farm chores, making crafts and working with the Village''s costumed historians. Groups are by age, with themes that change each week.', NULL, NULL, 315, 415, 390, 'week', FALSE, NULL, FALSE, TRUE, 'Refunds are available up to two weeks before your week''s program starts. You can switch weeks if there is space in your child''s age group; a change fee applies.', NULL, NULL, NULL, NULL, 2026, '242423b2-b46c-5f14-bbee-4db9e2d9cd08', 'discovery-adventures-sturbridge', ST_GeogFromText('SRID=4326;POINT(-72.0877 42.1048)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.osv.org/education/discovery-adventures/','https://www.osv.org/education/discovery-adventures/registration-information-and-packet/','https://www.osv.org/event/summer-discovery-adventures/']::text[], '2026-11-13', '2026-11-13', TRUE),
('EcoTarium Summer Discovery Camp and Vacation Week Camp', 'EcoTarium', 'https://ecotarium.org/camp/', NULL, 'reservations@ecotarium.org', '(508) 929-2703', '222 Harrington Way', 'Worcester', 'MA', '01604', 'Central & Western Massachusetts', 'day', ARRAY['STEM','nature']::text[], NULL, ARRAY['Outdoor exploration and shelter building','Animal encounters','Planetarium and space science','Rocket building','Engineering challenges','Forensic science mysteries','Behind-the-scenes zoo tour','Chemistry and slime','STEAM art projects']::text[], NULL, 5, 12, NULL, NULL, 'Week-long themed science and nature day camps at the EcoTarium museum in Worcester for ages 5-12, run 9 am-4 pm, Monday-Friday. Campers are grouped by age. There is also a Counselor-in-Training program for ages 13-15.', NULL, NULL, 365, 425, 395, 'week', NULL, FALSE, FALSE, TRUE, 'Deposits and camp fees are nonrefundable and nontransferable. Fees minus the $75 deposit can be refunded only if you cancel in writing by May 1 for summer camp, or four weeks before a vacation week camp. Later refunds are considered only for medical or emergency reasons.', 'The camp works with children who have school aides, IEPs or BIPs; a child''s aide is welcome at camp after CORI/SORI checks. Give the Camp Director at least three weeks'' notice of any accommodation, assistive device or major allergy. All food must be peanut and tree nut free, and staff are trained for allergy emergencies.', NULL, NULL, NULL, 2026, '2b07046b-56a5-55e6-9913-81c6069d2873', 'ecotarium-summer-discovery-camp-and-vacation-week-camp-worcester', ST_GeogFromText('SRID=4326;POINT(-71.8023 42.2626)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://ecotarium.org/camp/','https://ecotarium.org/wp-content/uploads/2024/10/Vacation-Summer-Camp-Cancellation-Refund-2024-2025.pdf','https://ecotarium.org/wp-content/uploads/2026/05/Camp-Caregiver-Handbook.docx.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('FA Summer (Falmouth Academy Summer Camps)', 'Falmouth Academy', 'https://www.falmouthacademy.org/summer/welcome', NULL, 'fasummer@falmouthacademy.org', '(508) 457-9696 x221', '7 Highfield Drive', 'Falmouth', 'MA', '02540', 'Central & Western Massachusetts', 'day', ARRAY['sports','arts','STEM','performing_arts','academic','nature']::text[], NULL, ARRAY['arts and crafts','outdoor play','cooperative team games','Rec Games (soccer, basketball, Wiffle Ball, floor hockey, pickleball, flag football, Capture the Flag, volleyball)','tennis lessons','Musical Theater Academy','pottery on the wheel','Rock Band','ukulele','Hip Hop, Ballet, Jazz and Lyrical dance','coding','robotics','engineering','seashore ecology','physics','forensics','academic tutoring']::text[], NULL, 5, 14, NULL, NULL, 'A weekly day camp at Falmouth Academy in Falmouth, MA for ages 5–14, split by age into Camp Mariner (5–6), Camp Seafarer (7–9) and Camp Navigator (10–14). Families choose half-day or full-day weeks with activities in sports, arts, STEM, nature and academics.', NULL, NULL, 375, 750, 750, 'week', NULL, NULL, FALSE, NULL, '2026 policy: written cancellations before May 1 get a full refund minus 50% of the deposit. Written cancellations after May 1 get 50% of the total camp cost back. No refund for cancellations made less than 14 days before camp starts.', NULL, NULL, NULL, NULL, 2026, '8e5c0793-43c8-5367-925f-1985d991a4c7', 'fa-summer-falmouth-academy-summer-camps-falmouth', ST_GeogFromText('SRID=4326;POINT(-70.5992 41.5949)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.falmouthacademy.org/summer/welcome']::text[], '2026-11-13', '2026-11-13', TRUE),
('Hitchcock Center Nature Summer Camp', 'Hitchcock Center for the Environment', 'https://www.hitchcockcenter.org/camp-programs/', 'https://campscui.active.com/orgs/HitchcockCenterfortheEnvironment?season=3749244', 'jeff@hitchcockcenter.org', '413-256-6006', '845 West Street', 'Amherst', 'MA', '01002', 'Central & Western Massachusetts', 'day', ARRAY['nature','STEM']::text[], NULL, ARRAY['Guided hikes and field investigations','Animal and insect observation','Mud and dirt play, slime making','Crafts and science projects','Nature-inspired inventing / biomimicry','Songs, stories and team-building games','Field trips','Sprinkler play','Caving, hikes and overnight camping (Leadership Training Camp)']::text[], NULL, 5, NULL, 0, 9, 'An outdoor nature day camp at the Hitchcock Center for the Environment in Amherst. Kids do hikes, animal observation, science and crafts. Nature Camp runs 8:45 AM to 3:00 PM for kids entering grades K to 6. Chickadee Camp is a half-day program (8:45 AM to 1:00 PM) for rising kindergartners. The Leadership Training Camp is for grades 7 to 9.', NULL, NULL, 305, 1080, 465, 'week', NULL, NULL, FALSE, TRUE, 'You can cancel yourself through your Active account. More than 90 days before your session starts: full refund minus a 6% platform fee. 30–90 days before: refund minus the $150 deposit. Less than 30 days before: no refund, unless the program is full and your spot gets filled, in which case you may get 50% back. There are no refunds for absences, sick days or vacations. Exceptions are made only for a health emergency, documented by a physician, that keeps the child out for the whole session.', 'The camp welcomes campers with social, emotional, physical, cognitive or behavioral challenges. If a child has a 1:1 aide at school, a 1:1 must also be provided at camp (a parent or guardian can do this). Campers must be able to move around on uneven terrain. Families should contact the Camp Director before enrolling to talk through accommodations. If needs are not disclosed, the child may be dismissed without a refund. Staff are trained to give EpiPens, and there is an individual health plan process for life-threatening allergies.', 'No swimming program is mentioned. Campers bring a swimsuit and towel for sprinkler play only.', NULL, NULL, 2026, '6da35310-2246-53e0-84e3-4a72e99e128e', 'hitchcock-center-nature-summer-camp-amherst', ST_GeogFromText('SRID=4326;POINT(-72.5199 42.3732)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.hitchcockcenter.org/camp-programs/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Nantucket Community Sailing Youth Camps & Classes', 'Nantucket Community Sailing', 'https://nantucketcommunitysailing.org/pages/youth-camps-classes', 'https://campscui.active.com/orgs/NantucketCommunitySailing?orglink=camps-registration', 'info@nantucketcommunitysailing.org', '508-228-6600', NULL, 'Nantucket', 'MA', '02584', 'Central & Western Massachusetts', 'specialty', ARRAY['sailing']::text[], NULL, ARRAY['Sailing','Sail racing','Regattas','Optimist dinghy sailing','420 double-handed sailing','Keelboat sailing (J70, Rhodes 19, IOD)','Seamanship']::text[], NULL, 4, 18, NULL, NULL, 'Half-day youth sailing classes for ages 4–18 in one- or two-week sessions. Younger and beginner sailors go to Polpis Harbor, and older or more advanced sailors go to Jetties Beach. Programs run Monday–Friday from June 21 to August 13, 2027.', NULL, NULL, 455, 1140, 475, 'week', NULL, NULL, NULL, TRUE, 'Cancel on or before April 30 for a 90% refund of tuition; from May 1 registrations are non-refundable. Transfers after June 1 cost 10% per sailor per session. Classes missed for weather are not made up or refunded.', NULL, 'Sailing is on open water at two sites. Polpis Harbor is a protected, calm harbor used for younger and beginner sailors. Jetties Beach on Nantucket Sound has open-water sailing for older and more experienced sailors. The page does not mention a swim test or swim requirements.', NULL, NULL, 2027, '8e3a506c-2f0f-56c2-b72a-17e0a186d022', 'nantucket-community-sailing-youth-camps-and-classes-nantucket', ST_GeogFromText('SRID=4326;POINT(-70.1022 41.2934)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://nantucketcommunitysailing.org/pages/faq','https://nantucketcommunitysailing.org/pages/youth-camps-classes']::text[], '2026-11-13', '2026-11-13', TRUE),
('Nantucket Nature Bound Program (Teen Naturalist Leadership Program)', 'Maria Mitchell Association', 'https://www.mariamitchell.org/teen-naturalist-leadership-program', NULL, 'info@mariamitchell.org', '(508) 228-9198', '4 Vestal Street', 'Nantucket', 'MA', '02554', 'Central & Western Massachusetts', 'day', ARRAY['nature','STEM']::text[], NULL, ARRAY['animal husbandry','museum operations','ecological fieldwork','snorkeling','seining','hiking','kayaking','beach combing','animal tracking','dissections','fish printing','plankton collection','orienteering','plant identification','ocean-themed art projects','community service projects']::text[], NULL, 13, 17, NULL, NULL, 'A set of week-long afternoon nature programs (1:15-4:15pm) for teens aged 13-17, run by the Maria Mitchell Association on Nantucket. Each week has its own theme, such as coastal ecology, marine and land ecology, cross-island hikes, or behind-the-scenes work at the museum and aquarium.', NULL, NULL, 665, 665, 665, 'week', NULL, NULL, NULL, TRUE, 'MMA may cancel a camper''s spot without a refund if the medical and registration forms are not received at least two weeks before the session starts. The page gives no general refund policy.', NULL, 'Campers must show strong swimming ability to snorkel (this applies to the Marine and Terrestrial Ecology and Aquarists of Tomorrow programs). Activities also include kayaking and seining.', NULL, NULL, 2026, '07e57978-1723-5de5-80a3-51d810b681c0', 'nantucket-nature-bound-program-teen-naturalist-leadership-program-nantucket', ST_GeogFromText('SRID=4326;POINT(-70.1022 41.2934)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.mariamitchell.org/scholarships-discounts','https://www.mariamitchell.org/teen-naturalist-leadership-program']::text[], '2026-11-13', '2026-11-13', TRUE),
('Springfield JCC Summer Camp', 'Springfield Jewish Community Center', 'https://www.springfieldjcc.org/camp/', NULL, 'info@springfieldjcc.org', '413-739-4715', '1160 Dickinson Street', 'Springfield', 'MA', '01108', 'Central & Western Massachusetts', 'day', ARRAY['sports','arts','faith','special_needs']::text[], NULL, ARRAY['Swimming','Ropes course','Archery','Indoor and outdoor sports and games','Arts & crafts','Jewish activities and celebrations','Counselors in Training (ages 14-15)']::text[], NULL, 5, NULL, NULL, NULL, 'A full day camp for children ages 5 and up on the Springfield JCC''s 20-acre campus. It offers Traditional Camp, Inclusion Camp and 2-4-1 Sports Camp, and teens ages 14-15 can join a Counselors in Training program. The camp is rooted in Jewish values and open to children of all backgrounds.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, NULL, 'The Inclusion Camp supports children with different abilities so they can take part in camp with their peers. Financial aid covers Inclusion Camp.', 'Campers swim in the JCC''s pool. Traditional Camp has two swim lessons and two free swims each week, with a swim test every Monday; lifeguards hold the required certifications.', TRUE, 'https://www.springfieldjcc.org/camp/', 2026, '6138f600-6761-57b9-a89a-5462cb1032fd', 'springfield-jcc-summer-camp-springfield', ST_GeogFromText('SRID=4326;POINT(-72.5898 42.1015)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.springfieldjcc.org/camp/','https://www.springfieldjcc.org/traditional-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('URJ Crane Lake Camp', 'Union for Reform Judaism', 'https://cranelakecamp.org/', 'https://cranelakecamp.org/register-login/', NULL, '(201) 722-0400', '46 State Line Road', 'West Stockbridge', 'MA', '01266', 'Central & Western Massachusetts', 'sleepaway', ARRAY['faith']::text[], NULL, NULL, NULL, NULL, NULL, 2, 11, 'Reform Jewish overnight camp in West Stockbridge, Massachusetts, run by the Union for Reform Judaism. Campers entering grades 2–10 come for 2-week, roughly 3–4-week, or full-summer sessions, and there is an Israel trip for grade 11.', NULL, NULL, 4450, 14700, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '3fc2d93e-602d-5db4-8285-b06915a965ed', 'urj-crane-lake-camp-west-stockbridge', ST_GeogFromText('SRID=4326;POINT(-73.388 42.3124)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://cranelakecamp.org/dates-rates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Wellfleet Bay Nature Camp', 'Mass Audubon', 'https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/wellfleet-bay/camp', NULL, NULL, '508-694-3620', '291 State Highway Route 6', 'Wellfleet', 'MA', '02663', 'Central & Western Massachusetts', 'day', ARRAY['nature']::text[], NULL, ARRAY['Habitat hikes','Tide pooling','Dip-netting','Wildlife observation','Nature crafts','Outdoor games','Science activities','Counselor-in-Training program (ages 14-17)']::text[], NULL, 4, 13, NULL, NULL, 'A Mass Audubon nature camp for ages 4–13 held at the 1,100-acre Wellfleet Bay Wildlife Sanctuary on Cape Cod, where campers explore the outdoors and learn about nature.', NULL, NULL, 60, 698, NULL, 'week', TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, TRUE, 'https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/wellfleet-bay/camp/about-camp', 2026, 'd692de39-7a0c-5b24-a0b1-c730f016ccd6', 'wellfleet-bay-nature-camp-wellfleet', ST_GeogFromText('SRID=4326;POINT(-70.0271 41.9168)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/wellfleet-bay','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/wellfleet-bay/camp','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/wellfleet-bay/camp/about-camp','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/wellfleet-bay/camp/programs-pricing']::text[], '2026-11-13', '2026-11-13', TRUE),
('Worcester Center for Crafts Youth Summer Program', 'Worcester Center for Crafts', 'https://worcestercraftcenter.org/youth-summer-program/', 'https://register.worcestercraftcenter.org/wconnect/ace/ShowSchedule.awp?Group=YC_SUM&Title=YOUTH:+Summer+Classes', NULL, '508-753-8183 ext 301', '25 Sagamore Road', 'Worcester', 'MA', '01605', 'Central & Western Massachusetts', 'day', ARRAY['arts']::text[], NULL, ARRAY['stained glass','kiln-formed glass','metalsmithing','chainmail jewelry','enameling','weaving','natural dyes','fiber arts','crochet','polymer clay','sculpture','game design','comic book and digital art','2D animation','movie making','streetwear fashion design']::text[], NULL, 7, 13, NULL, NULL, 'A full-day craft and art day camp in Worcester, MA for ages 7–13, running 9:00am–3:00pm. Each week you pick one class from separate tracks for ages 7–9 and 10–13, covering things like stained glass, metalsmithing, fiber arts and animation.', NULL, NULL, 252, 780, 420, 'week', TRUE, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '3c4cbe3a-b2ca-51b1-900b-7c99e29aeeda', 'worcester-center-for-crafts-youth-summer-program-worcester', ST_GeogFromText('SRID=4326;POINT(-71.8023 42.2626)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://worcestercraftcenter.org/youth-summer-program/']::text[], '2026-11-13', '2026-11-13', TRUE)
